def missing_runtime_reason(block_id: str, error: Any) -> str | None:
    """Why a block failure is "a component this deployment does not carry".

    Decided by the block's OWN declared runtime-error contracts, matched
    exactly against the answer -- never by words this module searches for in
    an arbitrary message. A contract that names an installation step is the
    provider-is-down class, and the component named is the one the contract
    names.
    """
    text = " ".join(str(error or "").split())
    if not text:
        return None
    contract = BLOCK_CONTRACTS.get(block_id) or {}
    for declared in contract.get("runtime_error_contracts") or []:
        declared_text = " ".join(str(declared or "").split())
        if not declared_text or declared_text.lower() != text.lower():
            continue
        if not _INSTALL_CONTRACT.search(declared_text):
            return None
        target = _INSTALL_TARGET.search(declared_text)
        component = target.group(1) if target else "an optional runtime"
        return "%s is not installed in this deployment: %s" % (
            component,
            declared_text,
        )
    return None


